#!/usr/bin/env bash
# Builds what the iOS app links: shellwing-mobile as a static library for
# iPhones and the Simulator (Apple silicon), wrapped in an XCFramework, and
# the Swift that calls it, generated by UniFFI.
#
#   scripts/build_ios.sh            release libraries
#   scripts/build_ios.sh --debug    quicker to build, slower to run
#
# Writes ios/Generated/ShellwingCore.xcframework and
# ios/Generated/shellwing_mobile.swift (neither is committed). Needs Xcode
# (not only the Command Line Tools), Zig 0.17 on PATH, and the two targets:
#   rustup target add aarch64-apple-ios aarch64-apple-ios-sim
set -euo pipefail

cd "$(dirname "$0")/.."
ROOT="$PWD"
PROFILE=release
FLAG=--release
if [[ "${1:-}" == "--debug" ]]; then
	PROFILE=debug
	FLAG=
fi

export DEVELOPER_DIR="${DEVELOPER_DIR:-/Applications/Xcode.app/Contents/Developer}"
# The oldest iOS the app runs on (ios/project.yml says the same).
export IPHONEOS_DEPLOYMENT_TARGET=17.0
CARGO="${CARGO:-cargo}"
OUT="$ROOT/ios/Generated"
LIB=libshellwing_mobile.a
TARGETS=(aarch64-apple-ios aarch64-apple-ios-sim)

# Zig 0.17.0's standard library does not compile for iOS: build with a
# patched copy of it (scripts/zig-0.17.0-ios.patch).
ZIG_LIB_IOS=$("$ROOT/scripts/zig_lib_ios.sh" "$ROOT/target/zig-lib-ios")
if [[ -n "$ZIG_LIB_IOS" ]]; then
	export ZIG_LIB_DIR="$ZIG_LIB_IOS"
fi

for t in "${TARGETS[@]}"; do
	echo "building shellwing-mobile for $t ($PROFILE)"
	"$CARGO" build -p shellwing-mobile --lib $FLAG --target "$t"
done

# The Swift side and the C header it calls through, read from the library's
# own metadata, so they always match what was built.
rm -rf "$OUT"
mkdir -p "$OUT/headers"
"$CARGO" run -q -p shellwing-mobile --features bindgen --bin uniffi-bindgen -- \
	generate --library "target/aarch64-apple-ios-sim/$PROFILE/$LIB" \
	--language swift --out-dir "$OUT/bindings"
mv "$OUT/bindings/shellwing_mobile.swift" "$OUT/"
mv "$OUT/bindings/shellwing_mobileFFI.h" "$OUT/headers/"
# Clang looks for module.modulemap by that name inside the headers folder.
mv "$OUT/bindings/shellwing_mobileFFI.modulemap" "$OUT/headers/module.modulemap"
rm -rf "$OUT/bindings"

xcodebuild -create-xcframework \
	-library "target/aarch64-apple-ios/$PROFILE/$LIB" -headers "$OUT/headers" \
	-library "target/aarch64-apple-ios-sim/$PROFILE/$LIB" -headers "$OUT/headers" \
	-output "$OUT/ShellwingCore.xcframework" >/dev/null
rm -rf "$OUT/headers"
echo "built $OUT/ShellwingCore.xcframework and $OUT/shellwing_mobile.swift"
